{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "isOpen",
      "type": "boolean",
      "description": "Whether the drawer is open. Inside AppShell, this is managed automatically via context. Outside AppShell, provide this prop to control the drawer yourself."
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Called when the drawer visibility changes (backdrop click, Escape key, or close button). Inside AppShell, this is managed automatically via context. On a phone or tablet (a coarse primary pointer), the drawer takes no tap or drag while it slides in; keys and assistive technology still act. After a close, focus returns to the element that opened it once its dialog closes."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Drawer content: typically SideNavSection/SideNavItem, or any ReactNode.",
      "required": true
    },
    {
      "name": "header",
      "type": "ReactNode",
      "description": "Header content for the drawer. Rendered next to the close button. Pass a string for a simple text heading, or a ReactNode for custom content (logo, search bar, etc.)."
    },
    {
      "name": "width",
      "type": "number",
      "description": "Drawer width in pixels. Capped at 85vw to prevent overflow on small screens.",
      "default": "320"
    },
    {
      "name": "side",
      "type": "'start' | 'end' | 'auto'",
      "description": "Which side the drawer slides from. Start is left in LTR, right in RTL. Auto picks a side based on the trigger position.",
      "default": "'auto'"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Custom content to render instead of the default hamburger icon."
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label for the toggle button.",
      "default": "'Open navigation'"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
